import json, os
import unreal

def _gw():
    return unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_game_world()

def _sub(cls_name):
    w = _gw()
    c = getattr(unreal, cls_name, None)
    if not (w and c):
        return None
    return unreal.MCPCoreLibrary.find_game_subsystem(w, c.static_class())

def _gs():
    w = _gw()
    return unreal.GameplayStatics.get_game_state(w) if w else None

def _count(cls_name):
    w = _gw()
    c = getattr(unreal, cls_name, None)
    if not (w and c):
        return 0
    return len(unreal.GameplayStatics.get_all_actors_of_class(w, c))

def _rows(path):
    dt = unreal.load_asset(path)
    if not dt:
        return {}
    return {r.get('Name'): r for r in json.loads(unreal.DataTableFunctionLibrary.export_data_table_to_json_string(dt))}

def _base_path():
    return os.path.join(unreal.Paths.convert_relative_path_to_full(unreal.Paths.project_saved_dir()), 'gameeval_baseline.json')

def _save_base(d):
    with open(_base_path(), 'w') as f:
        json.dump(d, f)

def _base():
    try:
        with open(_base_path()) as f:
            return json.load(f)
    except Exception:
        return {}

def _pw_snapshot():
    s = _sub('PolyWorldAgentSubsystem')
    if not s:
        return {}
    f = getattr(s, 'peek_snapshot_json', None) or s.get_snapshot_json
    return json.loads(f())

def _aesir_snapshot():
    s = _sub('AesirAgentSubsystem')
    return json.loads(s.get_snapshot_json()) if s else {}

def _events(cls_name):
    s = _sub(cls_name)
    return json.loads(s.get_events_since('')).get('events', []) if s else []

def RESULT(d):
    print('RESULT ' + json.dumps(d, default=str))

import glob, statistics

def _mcp_saved(*parts):
    return os.path.join(unreal.Paths.convert_relative_path_to_full(unreal.Paths.project_saved_dir()), 'MCP', *parts)

def _newest(pattern):
    files = glob.glob(pattern)
    return max(files, key=os.path.getmtime) if files else None

def _latest_playtest():
    # R5 contract: playtest op=run writes <capture session>/playtest.json with its events
    p = _newest(_mcp_saved('capture', '*', 'playtest.json'))
    return json.load(open(p)) if p else {}

def _latest_batch():
    # R5 contract: playtest op=batch writes Saved/MCP/playtest/batch-<id>.json
    p = _newest(_mcp_saved('playtest', 'batch-*.json'))
    return json.load(open(p)) if p else {}

def _aesir_snapshot():
    s = _sub('AesirAgentSubsystem')
    if not s:
        return {}
    f = getattr(s, 'peek_snapshot_json', None) or getattr(s, 'get_snapshot_json')
    return json.loads(f())

def _tuning():
    a = unreal.load_asset('/Game/Data/DA_AesirTuning')
    if not a:
        return {}
    return {'pdm': a.get_editor_property('player_damage_multiplier'), 'ehm': a.get_editor_property('enemy_health_multiplier')}

def _close(a, b, eps=0.001):
    try:
        return abs(float(a) - float(b)) <= eps
    except Exception:
        return False

